import json
import numpy as np

with open('table.json', 'r') as f:
    table_dict = json.load(f)

symbols = 'ABCDEFGHIJKLMNOPQRSTUVWXY'
sym_to_num = {s: i for i, s in enumerate(symbols)}

rule = np.zeros((25, 25, 25), dtype=np.int64)
for key, val in table_dict.items():
    l, c, r = sym_to_num[key[0]], sym_to_num[key[1]], sym_to_num[key[2]]
    rule[l][c][r] = sym_to_num[val]

def gf25_mul(a, b, irr_c):
    a0, a1 = a
    b0, b1 = b
    r0 = (a0*b0 + a1*b1*irr_c) % 5
    r1 = (a0*b1 + a1*b0) % 5
    return (r0, r1)

def gf25_add(a, b):
    return ((a[0]+b[0])%5, (a[1]+b[1])%5)

def gf25_neg(a):
    return ((5-a[0])%5, (5-a[1])%5)

# Try all permutations of symbols to GF(25) elements? Too many (25!)
# Instead, try systematic mappings

for irr_c in [2, 3]:
    for swap in [False, True]:
        def num_to_gf(n):
            if not swap:
                return (n%5, n//5)
            else:
                return (n//5, n%5)

        def gf_to_num(g):
            if not swap:
                return g[1]*5 + g[0]
            else:
                return g[0]*5 + g[1]

        e_num = int(rule[0][0][0])
        e = num_to_gf(e_num)

        one_gf = num_to_gf(1)

        # Find a: a * gf(l) = gf(rule(l,0,0)) - e for all l
        # From l=1: a * gf(1) = gf(rule(1,0,0)) - e
        target = gf25_add(num_to_gf(int(rule[1][0][0])), gf25_neg(e))

        a_found = None
        for an in range(25):
            ac = num_to_gf(an)
            if gf25_mul(ac, one_gf, irr_c) == target:
                a_found = ac
                break

        if a_found is None:
            continue

        target = gf25_add(num_to_gf(int(rule[0][1][0])), gf25_neg(e))
        b_found = None
        for bn in range(25):
            bc = num_to_gf(bn)
            if gf25_mul(bc, one_gf, irr_c) == target:
                b_found = bc
                break

        if b_found is None:
            continue

        target = gf25_add(num_to_gf(int(rule[0][0][1])), gf25_neg(e))
        d_found = None
        for dn in range(25):
            dc = num_to_gf(dn)
            if gf25_mul(dc, one_gf, irr_c) == target:
                d_found = dc
                break

        if d_found is None:
            continue

        errors = 0
        for l in range(25):
            for c in range(25):
                for r in range(25):
                    o_actual = int(rule[l][c][r])
                    l_gf = num_to_gf(l)
                    c_gf = num_to_gf(c)
                    r_gf = num_to_gf(r)
                    al = gf25_mul(a_found, l_gf, irr_c)
                    bc2 = gf25_mul(b_found, c_gf, irr_c)
                    dr = gf25_mul(d_found, r_gf, irr_c)
                    pred = gf25_add(gf25_add(gf25_add(al, bc2), dr), e)
                    pred_num = gf_to_num(pred)
                    if pred_num != o_actual:
                        errors += 1
                        if errors == 1:
                            pass

        label = f"irr_c={irr_c}, swap={swap}"
        print(f"{label}: a={a_found}, b={b_found}, d={d_found}, e={e}, errors={errors}/15625")

# Also try: what if there's no constant (purely linear)?
# And what about different irreducible polynomials?
# x^2 + x + 1: check if irreducible over F_5
# p(0)=1, p(1)=3, p(2)=7=2, p(3)=13=3, p(4)=21=1, all nonzero mod 5 -> irreducible
# x^2 + x + 2: p(0)=2, p(1)=4, p(2)=8=3, p(3)=14=4, p(4)=22=2, all nonzero -> irreducible

# Let me try more irreducible polys: x^2 + ax + b where it has no roots in F_5
# x^2 = -ax - b, so irr is defined by (a_coeff, b_coeff) where x^2 = -a_coeff*x - b_coeff
print("\nTrying more irreducible polynomials...")

def gf25_mul2(a, b, neg_a_coeff, neg_b_coeff):
    """x^2 = neg_a_coeff*x + neg_b_coeff"""
    a0, a1 = a
    b0, b1 = b
    # (a0+a1*x)(b0+b1*x) = a0*b0 + (a0*b1+a1*b0)*x + a1*b1*x^2
    # = a0*b0 + a1*b1*neg_b_coeff + (a0*b1+a1*b0 + a1*b1*neg_a_coeff)*x
    r0 = (a0*b0 + a1*b1*neg_b_coeff) % 5
    r1 = (a0*b1 + a1*b0 + a1*b1*neg_a_coeff) % 5
    return (r0, r1)

# Find all irreducible polynomials x^2 + px + q over F_5
irr_polys = []
for p in range(5):
    for q in range(5):
        # Check if x^2 + px + q has no roots in F_5
        has_root = False
        for x in range(5):
            if (x*x + p*x + q) % 5 == 0:
                has_root = True
                break
        if not has_root:
            # x^2 = -px - q
            neg_p = (5-p) % 5
            neg_q = (5-q) % 5
            irr_polys.append((neg_p, neg_q, p, q))

print(f"Found {len(irr_polys)} irreducible polynomials")

for neg_a, neg_b, p_coeff, q_coeff in irr_polys:
    for swap in [False, True]:
        def num_to_gf(n, sw=swap):
            if not sw:
                return (n%5, n//5)
            else:
                return (n//5, n%5)

        def gf_to_num(g, sw=swap):
            if not sw:
                return g[1]*5 + g[0]
            else:
                return g[0]*5 + g[1]

        e_num = int(rule[0][0][0])
        e = num_to_gf(e_num)
        one_gf = num_to_gf(1)

        target = gf25_add(num_to_gf(int(rule[1][0][0])), gf25_neg(e))
        a_found = None
        for an in range(25):
            ac = num_to_gf(an)
            if gf25_mul2(ac, one_gf, neg_a, neg_b) == target:
                a_found = ac
                break
        if a_found is None:
            continue

        target = gf25_add(num_to_gf(int(rule[0][1][0])), gf25_neg(e))
        b_found = None
        for bn in range(25):
            bc = num_to_gf(bn)
            if gf25_mul2(bc, one_gf, neg_a, neg_b) == target:
                b_found = bc
                break
        if b_found is None:
            continue

        target = gf25_add(num_to_gf(int(rule[0][0][1])), gf25_neg(e))
        d_found = None
        for dn in range(25):
            dc = num_to_gf(dn)
            if gf25_mul2(dc, one_gf, neg_a, neg_b) == target:
                d_found = dc
                break
        if d_found is None:
            continue

        # Quick check with a few random entries before full verification
        import random
        quick_errors = 0
        for _ in range(100):
            l = random.randint(0,24)
            c = random.randint(0,24)
            r = random.randint(0,24)
            o_actual = int(rule[l][c][r])
            l_gf = num_to_gf(l)
            c_gf = num_to_gf(c)
            r_gf = num_to_gf(r)
            al = gf25_mul2(a_found, l_gf, neg_a, neg_b)
            bc2 = gf25_mul2(b_found, c_gf, neg_a, neg_b)
            dr = gf25_mul2(d_found, r_gf, neg_a, neg_b)
            pred = gf25_add(gf25_add(gf25_add(al, bc2), dr), e)
            pred_num = gf_to_num(pred)
            if pred_num != o_actual:
                quick_errors += 1

        if quick_errors == 0:
            # Full verification
            errors = 0
            for l in range(25):
                for c in range(25):
                    for r in range(25):
                        o_actual = int(rule[l][c][r])
                        l_gf = num_to_gf(l)
                        c_gf = num_to_gf(c)
                        r_gf = num_to_gf(r)
                        al = gf25_mul2(a_found, l_gf, neg_a, neg_b)
                        bc2 = gf25_mul2(b_found, c_gf, neg_a, neg_b)
                        dr = gf25_mul2(d_found, r_gf, neg_a, neg_b)
                        pred = gf25_add(gf25_add(gf25_add(al, bc2), dr), e)
                        pred_num = gf_to_num(pred)
                        if pred_num != o_actual:
                            errors += 1

            label = f"x^2+{p_coeff}x+{q_coeff}, swap={swap}"
            print(f"*** {label}: a={a_found}, b={b_found}, d={d_found}, e={e}, errors={errors}/15625 ***")
